SET body_html = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;background-color:#f5f5f5;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#1e3a5f,#2563eb);padding:30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:24px;">3 Dicas Para Acelerar Sua Jornada</h1></td></tr><tr><td style="padding:30px;"><h2 style="color:#1e3a5f;margin-top:0;">Ola {{leadName}}!</h2><p style="color:#333;font-size:16px;line-height:1.6;">Com base no seu diagnostico, separamos 3 acoes rapidas que podem fazer diferenca imediata:</p><ol style="color:#333;font-size:16px;line-height:2;"><li><strong>Revise seu curriculo no formato americano</strong> — o formato brasileiro nao funciona nos EUA</li><li><strong>Traduza seus titulos profissionais</strong> — usar o titulo correto multiplica suas chances</li><li><strong>Identifique empresas que patrocinam visto</strong> — nem todas patrocinam, foque nas certas</li></ol><p style="color:#333;font-size:16px;line-height:1.6;">Quer ajuda com essas acoes? Nossa plataforma automatiza todas elas.</p><p style="text-align:center;margin:30px 0;"><a href="https://hub.euanapratica.com/assinar" style="background-color:#2563eb;color:#ffffff;padding:14px 28px;text-decoration:none;border-radius:8px;font-size:16px;font-weight:bold;display:inline-block;">Conhecer a Plataforma</a></p><p style="color:#666;font-size:14px;margin-top:30px;">Abraco,<br><strong>Equipe EUA na Pratica</strong></p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px;text-align:center;"><p style="color:#999;font-size:12px;margin:0;">EUA na Pratica. Todos os direitos reservados.</p><p style="margin:8px 0 0;"><a href="{{unsubscribeLink}}" style="color:#999;font-size:12px;">Cancelar inscricao</a></p></td></tr></table></td></tr></table>{{trackingPixel}}</body></html>'
